const uint8_t *data = buffer;
int res = LFS_CMP_EQ;
lfs_off_t i = 0;
while (i < size) {
    uint8_t dat[8];
    lfs_size_t diff = lfs_min(size-i, sizeof(dat));
    int err = lfs_bd_read(lfs, pcache, rcache, diff, block, off+i, &dat, diff);
    if (err) {
        return err;
    }
    for (lfs_size_t j = 0; j < diff; j++) {
        if (dat[j] < data[i+j]) {
            res = LFS_CMP_LT;
            break;
        } else if (dat[j] > data[i+j]) {
            res = LFS_CMP_GT;
            break;
        }
    }
    if (res != LFS_CMP_EQ) {
        return res;
    }
    i += diff;
}
return res;

